//! Le guide : les deux moitiés de wisq, et ce que chacune demande.
//!
//! Des données, pas du balisage : `crate::doc` est le seul rendu, et une
//! traduction manquante ne compile pas.

use crate::doc::{Block, DlItem, Doc, Tone};

pub static DOCS_EN: Doc = Doc {
    title: "Guide",
    lede: "How the two halves work, and what each one asks of you: a VM on your own hardware, or Linux on the phone itself.",
    blocks: &[
        Block::P("wisq does two separate things, and which one you want decides everything that follows. Reaching a virtual machine that runs on a Mac, a PC or a NAS gives you a full desktop at the speed of that machine. Booting Linux on the phone itself gives you a shell with no network at all. Neither needs a jailbreak."),
        Block::Note { tone: Tone::Info, text: "The app speaks only French for now, so its buttons and menus are quoted here as it shows them — « Nouvelle machine », « Importer depuis un agent ». Everything starts from the + menu above the machine list." },
        Block::H2("Remote: a VM on your own hardware"),
        Block::P("wisq speaks three console protocols. RFB 3.8 — VNC — reaches anything that exposes a VNC console: QEMU, libvirt, VirtualBox, Proxmox, a Raspberry Pi running x11vnc, a Mac sharing its screen. SPICE reaches what libvirt hosts usually publish instead, and carries more: the clipboard, files sent into the guest, its own image codecs, and sound both ways — on the wire, for now, as the SPICE section below explains. RDP reaches Windows guests, and it comes with a caveat worth reading before you rely on it: wisq speaks RDP's historic security and nothing else yet, which does not authenticate the server — the certificate is signed by a key Microsoft published in 1998. A host that demands NLA or TLS is refused by name rather than worked around, and the clipboard and sound travel on virtual channels wisq does not open."),
        Block::Code { code: "qemu-system-x86_64 -m 2048 -vnc :1 -hda disk.qcow2\n\n# or expose a display that already exists\nx11vnc -display :0 -rfbport 5901", caption: Some("Two ways to get a console worth connecting to") },
        Block::H3("Adding a machine by hand"),
        Block::Ol(&["Open the + menu, choose « Nouvelle machine » and give the machine a name you will recognise.", "Enter the address — a host, or host:port. A VNC display of :1 means port 5901: the port is 5900 plus the display number. libvirt hands out SPICE ports the same way, from 5900 upward, and RDP's own port is 3389. Without a port, wisq tries the protocol's usual one.", "Pick the protocol. RDP adds a user name field; VNC and SPICE only ever ask for a password.", "Enter the password if the server asks for one; it is stored in the iPhone Keychain, never in the machine list and never in an iCloud backup.", "Save, then tap the machine to connect."]),
        Block::P("Classic VNC authentication is DES over a challenge — weak by design — and it only ever reads the first 8 characters of a password: a longer one is not stronger, just cut. It is also the only RFB authentication wisq speaks besides none, so a server that offers nothing else, VeNCrypt alone for instance, is refused with « aucune méthode d'authentification commune ». Under « Chiffrement », TLS wraps the whole connection from its first byte, for a server that listens behind TLS; « TLS épinglé par empreinte » accepts only the certificate whose SHA-256 fingerprint you type in — openssl x509 -fingerprint -sha256 prints it — and without a fingerprint it is ordinary TLS validated by the system, which the editor says under the picker."),
        Block::P("The list can be searched by name, host or tag. Swiping a row to the left offers « Modifier » and « Supprimer », plus « Éteindre » on a machine bound to an agent."),
        Block::Note { tone: Tone::Warn, text: "The agent speaks TLS by default: a self-signed certificate whose fingerprint travels in the pairing link, pinned by the app, so there is no certificate authority in the picture. Run it with --no-tls only for a tunnel that already encrypts. The console itself is a different matter — plain VNC and plain SPICE are unencrypted by design, so use a network you trust or a tunnel you already run, WireGuard or Tailscale." },
        Block::H3("Which protocol for which host"),
        Block::Table { columns: &["Host", "Console", "What to know"], rows: &[&["QEMU on its own", "VNC with -vnc :N, at 5900 plus N; SPICE at the port you give it", "The agent has no backend for QEMU without libvirt yet: start the VM yourself, and type the SPICE port — the one wisq guesses is 5900."], &["libvirt — virsh, virt-manager", "SPICE or VNC, whichever the domain declares; automatic ports from 5900 upward", "What the agent drives, through virsh; its bureau command builds a SPICE desktop from an installation image."], &["Proxmox", "SPICE, through the .vv file its console hands out", "wisq reads those files, but its parser is tested on files shaped after Proxmox's, not against a Proxmox host. The agent has no Proxmox backend yet; it is on the roadmap."], &["Windows", "RDP, on port 3389", "Modern Windows demands NLA by default, which wisq does not speak yet: such a host is refused by name, so a Windows machine left at its defaults is out of reach for now."], &["A Linux desktop", "VNC through x11vnc, or RDP through xrdp", "x11vnc shares a display that already exists. xrdp is the server wisq's RDP was written and measured against."]] },
        Block::H3("Opening a .vv or .rdp file"),
        Block::P("When a hypervisor or a gateway hands you a connection file, nothing needs retyping. Get the file onto the phone — AirDrop, Mail, Files — then choose « Ouvrir un fichier .vv ou .rdp » in the + menu. The picker accepts any file on purpose, because these files arrive under whatever name their sender gave them: what wisq does with one is decided by reading it. A [virt-viewer] section makes a .vv, key:type:value lines make an .rdp, and an .rdp saved by Windows in UTF-16 is read as such. A host that is not a valid address is refused right there, not at connection time. Otherwise the machine opens in the editor rather than being saved outright, named after its host and tagged « importé », so you see what came in before it reaches your list."),
        Block::Ul(&["From a .vv: the host, the port — the TLS port when the file offers one, and the machine is then marked TLS — the protocol, SPICE unless the file names another, and the password, which goes to the Keychain. It is often a one-shot ticket, good for a single connection.", "Not from a .vv: the certificate subject a TLS file may name. The machine has nowhere to keep it, so the import claims TLS validated by the system rather than a pin it could not honour.", "From an .rdp: the address, an IPv6 one in brackets included, the port — 3389 when the file names none — and the user name. The saved password is never read: it is encrypted to the computer that wrote the file.", "Not from an .rdp: the screen size. It describes the monitor of whoever saved the file, and on a phone, the size of the view is what counts."]),
        Block::H2("In a session"),
        Block::P("One finger always drives the pointer. In trackpad mode — the default — it moves the cursor relative to where it was, as a laptop's trackpad does, and a tap clicks where the cursor stands; in direct-touch mode the cursor goes to the finger. Trackpad is the default because aiming at a small button with a fingertip does not work, and the drawn cursor gives back what the finger hides."),
        Block::Table { columns: &["Gesture", "By default", "Can be changed"], rows: &[&["One finger sliding", "moves the pointer", "no"], &["Tap", "left click", "no"], &["Two-finger tap", "right click", "yes"], &["Long press", "right click", "yes, « Glisser » included, which holds the button down"], &["Two fingers sliding", "scroll wheel", "yes"], &["Three fingers sliding", "moves the view", "yes"], &["Three-finger swipe", "up shows the keyboard, down hides it", "on or off"], &["Pinch", "zoom", "no"], &["Double tap", "shows or hides the top bar", "no"]] },
        Block::P("The choices are the same for every gesture — nothing, a left, right or middle click, « Glisser », « Déplacer l'écran », the wheel, the keyboard — and they are set per machine, in its editor under « Gestes », because the right answer depends on whether the remote desktop fits on the phone's screen: moving a view that has nowhere to go is a wasted gesture. The same editor sets the pointer speed, natural scrolling, haptic feedback and inertia: with it on, the pointer and the wheel keep going for a moment after the finger lifts."),
        Block::P("Two details are there for the guest's sake. A synthesised click or keystroke sends its press and its release 50 ms apart, because a guest that samples its input on a timer sees nothing of two edges arriving together. And input reaches the guest in the order it happened: a click that raced ahead of the move that placed it would land in the wrong spot. When the server hands over its cursor image — VNC's cursor encoding, SPICE's cursor channel — the phone draws it at its hotspot, in a layer of its own, so it follows the finger without redrawing the desktop; in trackpad mode a ring stands in until it arrives."),
        Block::H3("Keyboards"),
        Block::P("A hardware keyboard works as soon as the session is open: an invisible view listens for the whole session, and the keys it reports are translated into what the protocol wants — X11 keysyms for VNC, scancodes for SPICE and RDP. « ⌘ vers la touche Super » decides where Command goes: to the guest's Super key or, switched off, to Control, which is what macOS habits want in a terminal. The on-screen keyboard comes and goes with the keyboard button in the top bar, or with a three-finger swipe. The ⌘ button beside it opens a row of the keys a phone keyboard lacks: esc, tab, ctrl, alt, ⇧ and ⌘, the arrows, home, end, page up and down, delete, and « Fn » for F1 to F12. Its modifiers are sticky — tap ctrl, then a letter, and the pair is sent together."),
        Block::H3("The bar at the top"),
        Block::Ul(&["The close button ends the session.", "The clipboard button sends the phone's clipboard text to the guest. The other way needs no button: text copied in the guest lands on the phone's clipboard by itself. VNC and SPICE carry it; RDP does not yet.", "The share button, on SPICE sessions only, is for sending a file into the guest — the SPICE section below says why it does not reach one yet.", "The ⌘ and keyboard buttons, described above.", "A double tap on the desktop hides the bar, and another brings it back."]),
        Block::H3("Display settings"),
        Block::Dl(&[DlItem { term: "« Échelle »", detail: "« Ajusté » fits the whole desktop on the screen, letterboxed; « 1:1 » shows one remote pixel per pixel and you pan around; « Rempli » stretches it to fill, ignoring the aspect ratio." }, DlItem { term: "« Suivre la résolution de l'appareil »", detail: "Asks the server to resize its desktop to the phone's view. A VNC server that supports resizing does. RDP fixes its size when the session opens, and wisq cannot renegotiate it yet; SPICE resizes through the agent in the guest, which wisq does not drive yet." }, DlItem { term: "« Mode bas débit »", detail: "VNC only. Puts the encodings that compress hardest first and asks the server for more compression than its default. It does not lower the colour depth." }, DlItem { term: "« JPEG (avec pertes) »", detail: "VNC only, through Tight: lets the server send JPEG, at a quality from 0 to 9. Off, the session stays lossless — no quality is announced, so a compliant server never sends JPEG. On a cellular link, lossy is usually the right trade." }, DlItem { term: "« Garder l'écran allumé »", detail: "Keeps the phone from locking while the session is open. On by default." }]),
        Block::H3("When the network drops"),
        Block::P("A phone changes networks all the time, and every handoff kills the socket. wisq keeps the session and rebuilds the connection underneath it: up to 5 attempts, waiting 1 second before the first and doubling each time. Meanwhile the screen gives way to « Reconnexion (tentative n)… »: every attempt starts afresh, because a compression dictionary carried over from the dead connection would decode to garbage, and what you type in the meantime is dropped rather than queued. When wisq gives up, it shows the reason with « Réessayer » and « Fermer ». A connection that stayed up 10 seconds earns the whole budget back; one that comes up and falls over at once does not, so a host that accepts and drops cannot keep the phone retrying forever."),
        Block::P("It never retries a refusal. A wrong password, a failed negotiation, a certificate that does not match: those end the session with their reason, because hammering a server with a bad password can lock the account, and a protocol mismatch will not fix itself. One known limit: a reconnection dials the port the session started on. If libvirt gave the VM another one in between, because it was restarted from the host, close the session and connect again from the list, which asks the agent afresh."),
        Block::H2("SPICE: what travels besides the screen"),
        Block::P("SPICE opens one connection per channel — display, inputs, cursor, the guest's sound, the phone's microphone — and everything but the display is best effort: a server that offers no cursor channel still gives you a usable screen. The main channel also carries the guest agent, and the clipboard and file transfers go through it. That has a consequence inside the guest: spice-vdagent has to run there, and the domain needs the com.redhat.spice.0 channel it talks through — the one the agent's bureau command adds by itself. Without them, the screen and the inputs still work, the clipboard simply stays silent, and a file transfer says « aucun agent ne tourne dans l'invité pour recevoir le fichier »."),
        Block::P("Copy something in the guest and it lands on the phone's clipboard; the clipboard button sends the phone's text the other way. File transfer is written down to the protocol: a file streams to the guest's agent a chunk at a time, never whole in memory, so its size is the guest's problem rather than the phone's, and when the guest refuses, the message says why — transfers disabled, not enough room, with the figures. The session screen does not reach it yet. The share button looks for a SPICE session where the app holds the reconnecting wrapper around one, so today it answers « cette session n'a pas d'agent SPICE pour recevoir un fichier » whatever the guest runs — a known defect, not a missing agent. The clipboard is tested against the protocol and has not yet been seen working against a guest booted with its agent running, and the repository's Ubuntu walkthrough says so."),
        Block::P("Sound is the honest exception. The playback channel — the guest's sound — and the record channel — the phone's microphone, towards the guest — are both spoken and tested, in raw PCM only: Opus and CELT are named rather than decoded, because compressed bytes played as samples are noise at full volume. What is not written yet is the part that needs a speaker and a microphone. Nothing on the phone plays the guest's sound or captures yours today, so a SPICE session is silent, and that is not a setting. Video streams follow the same rule of naming: MJPEG is decoded where the platform has a JPEG decoder, and the other codecs a server may choose are named to you rather than shown as a frozen rectangle."),
        Block::H2("The agent: turning a VM on before connecting"),
        Block::P("Without the agent wisq still works, as long as the VM is already running. The agent is what turns \"one more VNC client\" into \"my machines, from my phone\": tapping a powered-off VM boots it, waits for its console and connects to whatever port it landed on."),
        Block::P("The daemon has no service mode of its own, and an argument it does not know stops it with « argument inconnu ». What keeps it alive across reboots is whatever starts it — a launchd agent on macOS, a systemd user unit on Linux — and the token and the pairing links are then in that job's log — ~/Library/Logs/wisq-agent.log on a Mac, journalctl --user -u wisq-agent on Linux. Run it with --demo first if you want to see the phone side working before pointing it at a hypervisor: it serves two fake VMs with real state transitions, and no console behind them."),
        Block::P("On first start the daemon prints a pairing link per reachable address, and a QR code when qrencode is installed. Open one on the iPhone — scan it, or paste it — and wisq lands on the import screen with the address and token already filled in."),
        Block::Code { code: "wisq-agent en écoute sur le port 7442 (virsh)\njeton : k3f9x2m8q1w7e4r6t5y0u8i2o4p6a1s3\nappairage :\n  wisq://agent?host=nas&port=7442&token=…&name=nas", caption: Some("What the daemon prints") },
        Block::P("The token is generated once and kept in ~/.wisq-agent/token with owner-only permissions. Revoking access is deleting that file and restarting the daemon — deleting it under a running daemon changes nothing, since the token is read once at startup — and every phone paired with the old token then has to pair again."),
        Block::H3("Pairing, discovery and the certificate"),
        Block::P("The daemon prints one link per address — its host name first, then each IPv4 address it finds — and the QR code carries the first. If that one does not answer from the phone, paste one of the others. Besides the token, each link carries the SHA-256 fingerprint of the daemon's self-signed certificate: that is what makes the phone speak HTTPS to it and accept exactly that certificate, with no authority and no name check. The certificate never rotates by itself, so links already printed keep working; deleting tls-certificate.der and tls-key.der from ~/.wisq-agent is the rotation, and it invalidates every old link on purpose."),
        Block::P("The import screen also lists the agents it hears on the local network — the daemon announces itself over Bonjour under its host name when avahi-publish-service or dns-sd is present — and a tap fills in the address. An address found that way, or typed by hand, has no fingerprint to pin, so the phone speaks plain HTTP to it: right for a daemon run with --no-tls, and answered by a daemon in its default mode with « cet agent parle TLS ». For that one, the pairing link is the way in."),
        Block::H3("Daemon options"),
        Block::Dl(&[DlItem { term: "--port N", detail: "The port to listen on; 7442 by default." }, DlItem { term: "--token SECRET", detail: "A token of your choosing. Without it, the daemon uses the one in ~/.wisq-agent/token, drawn from the system's random source on first start." }, DlItem { term: "--no-tls", detail: "Plain HTTP, for a tunnel that already encrypts. The token is still required, and the pairing links then carry no fingerprint." }, DlItem { term: "--demo", detail: "Two fake VMs instead of libvirt. A start goes through the starting state, which the app shows as « Démarrage… »; a polite stop takes a moment, a forced one is immediate." }, DlItem { term: "--virsh PATH", detail: "The virsh to drive; /usr/bin/virsh by default." }, DlItem { term: "--demo-delay MS", detail: "How long a demo boot takes. It exists so the tests that run the real daemon against the app's own client can cross the starting-to-running transition quickly." }]),
        Block::H3("Booting and powering off from the phone"),
        Block::P("A machine imported from an agent is bound to it; one added by hand can be bound in its editor, under « Démarrer via un agent », with the VM's identifier and the token. Connecting then goes through the agent first. If the VM is off, the agent starts it — unless « Démarrer la VM à la connexion » is off, and then wisq says so instead — and the phone asks for the VM's state every 2 seconds, for up to 90, until it is running and announces a console port. Both halves count: libvirt says running as soon as the domain exists, and it opens the console port at that moment, while the guest behind it may still take tens of seconds to have anything to show. The console is then reached on the agent's host, at the port and in the protocol the agent just gave — which is why a port that moves between boots does not matter on this path."),
        Block::P("To power a VM off, swipe its row to the left, choose « Éteindre », then « Demander l'arrêt ». That is the ACPI button: the guest is asked, and may take a minute to comply — or never, if it has no ACPI handler, since nothing in the protocol can force it. wisq watches for up to 90 seconds; past that it says « L'invité n'a pas répondu » and offers « Couper l'alimentation », the power cord, which stops the VM at once and loses whatever was not saved."),
        Block::H3("A desktop from an installation image"),
        Block::P("wisq-agent bureau builds the machine there is to connect to. Writing a libvirt domain by hand means knowing the graphics model that suits the desktop's compositor, the boot order, the guest agent's channel and the SPICE password — four chances to go wrong, three of which end as a black screen with no message. Hand the command an installation image instead: it creates a qcow2 disk, writes the domain, defines and starts it, then prints what to type into wisq. Inside: the image booted before the disk and attached read-only, a USB tablet — SPICE sends absolute coordinates, which is what a finger produces, and a relative mouse drifts until it cannot be placed — the ich9 sound card, the guest agent's channel, and a SPICE password drawn from /dev/urandom."),
        Block::Code { code: "wisq-agent bureau --image ~/debian.iso\n\n…\nLa machine « debian » tourne.\n\nDans wisq, ajoutez une machine :\n  hôte      nas.local\n  protocole SPICE\n  port      celui que l'agent annonce pour cette machine\n  mot de passe  …\n\nLe mot de passe n'est écrit nulle part ailleurs : notez-le maintenant.", caption: Some("From an image to a running desktop, and what the command prints last") },
        Block::Dl(&[DlItem { term: "--image PATH", detail: "The installation image, and the only option required." }, DlItem { term: "--nom N", detail: "The machine's name; by default, the file's name without its extension." }, DlItem { term: "--memoire MiB, --processeurs N", detail: "4096 MiB and 4 processors unless told otherwise." }, DlItem { term: "--disque GiB", detail: "The size of the disk, 64 GiB by default, created sparse. A disk of the same name that already exists is reused, never overwritten: redefining a machine must not erase a system already installed on it." }, DlItem { term: "--video virtio|qxl", detail: "virtio by default, the right model for a Wayland desktop — Hyprland, GNOME, KDE; qxl for a light X11 one. Getting it wrong breaks nothing: the machine boots and the screen stays black." }, DlItem { term: "--ecoute ADDRESS", detail: "Where the desktop listens; every interface by default, so the phone can reach it. The generated password is what guards it, and it is printed once, nowhere else." }, DlItem { term: "--dossier DIR", detail: "Where the disk and the domain's XML go; ~/wisq-disques by default. The XML stays there to be read again." }, DlItem { term: "--montrer", detail: "Prints the domain on standard output and creates nothing, to read or adapt it. It needs no libvirt at all." }]),
        Block::P("The accelerator is read from virsh capabilities rather than guessed: KVM on Linux, HVF on a Mac, and otherwise QEMU's own interpreter, which the command then says out loud, because an interpreted desktop runs, slowly. To reach the result, import it from the agent, which knows its port, and add the printed password in the machine's editor. The command was run for real against libvirt and QEMU with an Alpine image: the disk is created, the domain defined and started, and wisq's SPICE client connects with the generated password and receives the desktop's pixels, while a wrong password is refused. Installing a guest all the way from its installer has not been verified."),
        Block::H2("Local: Linux on the phone itself"),
        Block::P("The local side is two interpreted computers, and wisq picks between them by reading the file you bring. The RISC-V one is one rv32ima hart, 64 MB of RAM by default and up to 2 GB if you ask for it, an 8250 UART, a CLINT timer; it boots a real Linux kernel to a login prompt in a fraction of a second. The other is an x86-64 PC, described below. Both run with no network and no host."),
        Block::Ol(&["Get a kernel. For the RISC-V machine, an rv32ima nommu image — ready-made ones live in the mini-rv32ima project. For the PC, a bzImage and its initramfs.", "Put the files somewhere the Files app can reach — iCloud Drive, or On My iPhone.", "In wisq, choose « Linux local (sur ce téléphone) » in the + menu and import them, one at a time.", "Optional: import a filesystem or installer image too, of any size, and pick it under the kernel as its disk. The guest sees it on /dev/vda.", "Tap the kernel. The console appears as the kernel writes to its serial port; type into the field under it and press « Entrée », or send ^C."]),
        Block::P("On the RISC-V machine the virtual clock advances with executed instructions rather than wall time, so the same image boots the same way on every device — which is also what makes the boot testable in CI."),
        Block::H3("Which machine a file gets"),
        Block::P("wisq reads the first 40 KiB of a file — enough to reach an installer's volume descriptor, never the whole image — and decides from them. It knows the wrappers a kernel actually ships in: ELF, bzImage, the Image of ARM64 and of RISC-V, ARM's zImage, and U-Boot's uImage, which names its own architecture. It recognises every architecture Linux has a directory for under arch/, plus a few it carried long enough for images to linger — x86, ARM, RISC-V, MIPS, PowerPC, IBM Z, SPARC, LoongArch and the rest — and it executes two: 32-bit RISC-V and x86-64. A kernel for any other is refused with its architecture named, which tells you what to look for instead; a 32-bit x86 or a 64-bit RISC-V kernel is refused too, since neither has a core. A file nothing recognises is not refused: it is tried on the RISC-V machine, because a raw image with no header may still be a kernel."),
        Block::Table { columns: &["What you bring", "What wisq does with it", "Who decides"], rows: &[&["A kernel", "boots it, on the core its bytes call for", "the bytes"], &["An initramfs", "hands it to the PC kernel, which unpacks it; the RISC-V machine refuses one by name", "its name, then you"], &["A disk image", "plugs it in on /dev/vda", "you, in the kernel's « Disque » menu"], &["An installation image", "takes its kernel and initramfs out, and plugs the image in as the disk", "the boot recipe inside it"]] },
        Block::P("An initramfs goes to the kernel whose name answers it — vmlinuz-lts and initramfs-lts, in Alpine's naming — or, failing that, to the only one in the library. The bytes cannot settle it: a compressed kernel and a compressed initramfs are both a gzip stream, so the name decides, and then you."),
        Block::H3("The x86-64 machine"),
        Block::P("The PC machine interprets x86-64 and boots a stock Alpine kernel with its initramfs. Its serial port passes the kernel's own driver probe, so user space gets a real console; around it are a timer and an interrupt controller, a PCI bus, and a virtio disk the kernel finds over MMIO or over PCI. Measured on the same images as QEMU, Alpine's init ends on « Mounting boot media: failed. » and opens the initramfs's emergency shell — exactly where QEMU ends — and you can type into it. Expect to wait: where the RISC-V kernel reaches its prompt in tens of millions of instructions, that takes some 4 billion. A line under the console counts them and gives the speed, and says « figée » with the address when nothing has moved for a moment, because a kernel that prints a few lines and then goes quiet looks exactly like a dead one."),
        Block::P("A PC kernel gets what its memory slider says, but never less than 128 MB: below that, its kernel has no room to decompress itself, and with the slider left at its default that floor is what it gets. The machine knows how to hand the kernel a screen, and a real Alpine kernel finds and maps it under test, but the app attaches none yet: the PC is a console, like the other machine. Neither has a network device."),
        Block::H3("Installation images"),
        Block::P("An installer image is no longer refused in the build that carries the Rust core, which is the one the app ships with. wisq reads the boot recipe inside it — syslinux, grub or systemd-boot — takes the kernel and the initramfs out into its own storage, and starts them with the command line the recipe gives: read, never invented, because a kernel started without its own does not find its root, and the failure lands far from its cause. Only quiet is removed, and wisq's serial console is added last, since it is the only output there is. The image itself stays where it is and becomes the disk, read sector by sector, because the root that command line names lives there. A recipe that promises an initramfs the image does not hold is a refusal rather than a boot that dies three hundred lines later. On a live image, whose root is read-only, everything you do lives in RAM, and the snapshot described below is what keeps it. Deleting the image deletes what was unpacked from it. How far a given distribution then gets on the interpreter is for the console to tell; this guide does not promise it."),
        Block::H3("Memory"),
        Block::P("Each kernel in the list has its own memory slider, remembered under the file's name. It offers powers of two from 16 MB up, but only as far as the phone allows at that moment: the smallest of what iOS says the app may still allocate, less 256 MB the app keeps for itself; the phone's own memory, less 2 GB; and what the architecture allows — 2 GB for the RISC-V machine, the last byte a rv32 processor can address, and 16 GB for the PC. The ceiling is read again at boot, and a machine that no longer fits is refused with an explanation rather than started and killed by iOS halfway through. Changing the setting restarts from the kernel: a snapshot taken at another size cannot be resumed."),
        Block::H3("Suspension and resume"),
        Block::P("Leaving the console does not stop the machine; it suspends it. Leave the screen, or let iOS take the app away, and wisq writes the whole machine to a snapshot — processor, RAM, pending input, output not yet shown, the disk's writes flushed — and the next visit resumes it where it stood, console included. A RISC-V machine that has reached its login prompt weighs about 17 MiB saved, because the snapshot keeps what the guest touched rather than what it was given. « Arrêter » ends the machine and forgets its snapshot; « Oublier » throws the snapshot away without stopping the running machine, for a guest that is wedged and should come back clean. Snapshots are filed under the kernel's bytes, not its name, so a different kernel that happens to be called Image never inherits another's machine; changing a kernel's memory or its disk forgets its saved machines."),
        Block::H3("The disk"),
        Block::P("wisq emulates the device, and cannot add a block driver to the kernel you brought. Many rv32 nommu kernels have none, and one that has none will never touch it — so the device counts its requests, and wisq tells you at the end of the session rather than leaving you with a disk that is silent for a reason you cannot see. The image is read in place, whatever its size — there is no ceiling any more. What the guest writes goes into a layer beside it — the touched sectors packed back to back, 512 bytes each, and a map naming them — written as it happens, so it survives suspension and restarts; the file you imported never changes."),
        Block::P("The + menu holds one more entry, « Le bureau est-il possible ? ». It spends a few seconds measuring whether WebKit compiles WebAssembly on this very phone — the one unknown the work on a local desktop depends on, since iOS allows no JIT and WebAssembly that WebKit compiles is the only door it leaves open. It does nothing else."),
        Block::H2("When something does not work"),
        Block::Dl(&[DlItem { term: "The screen stays black after connecting", detail: "The server accepted the connection but is not sending updates. Check that the VNC server is attached to a display that exists — a headless QEMU with no -vga will connect and show nothing." }, DlItem { term: "Colours look wrong", detail: "Report it. wisq negotiates a pixel format for rendering rather than accepting the server's, and a mismatch is a bug on our side, not a setting on yours." }, DlItem { term: "VNC: « aucune méthode d'authentification commune »", detail: "The server offers no RFB authentication wisq speaks; only none and the classic VNC password are. A server set to VeNCrypt alone, for instance, has to offer the VNC password as well." }, DlItem { term: "« Cette machine demande un mot de passe »", detail: "The server wants the VNC password and the machine has none saved. Add it in the editor; it goes to the Keychain." }, DlItem { term: "RDP: « ce serveur exige l'authentification réseau (NLA) »", detail: "Modern Windows asks for NLA by default, and wisq does not speak it yet: it refuses by name rather than failing halfway through the handshake, and nothing on the phone changes that. The same goes for « ce serveur exige TLS »: wisq cannot start TLS inside a connection that is already open." }, DlItem { term: "A SPICE session has no sound", detail: "Expected, for now. The sound channels are spoken and decoded, but nothing on the phone plays them yet. It is not a setting." }, DlItem { term: "The clipboard stays silent", detail: "spice-vdagent is not running in the guest, or the domain has no com.redhat.spice.0 channel for it to talk through. The screen and the inputs need neither. Over RDP the clipboard does not travel at all yet. A file send that says the session has no SPICE agent is the known defect described in the SPICE section, whatever the guest runs." }, DlItem { term: "The VM came back on another port", detail: "libvirt allocates console ports at each start, from 5900 upward, so a VM restarted from the host may land elsewhere. A machine bound to the agent asks for the port each time you connect from the list; a session reconnecting by itself still dials the old one, so close it and connect again. A machine typed in by hand keeps the port you gave it: bind it to the agent, or write the port into the domain's definition." }, DlItem { term: "Importing from an agent answers « cet agent parle TLS »", detail: "The address was typed, or picked from the agents found on the network, so there was no fingerprint to pin and the phone spoke plain HTTP. Open the pairing link instead — or run the daemon with --no-tls, behind a tunnel." }, DlItem { term: "A paired agent answers « jeton manquant ou invalide »", detail: "The token in the link is no longer the one in ~/.wisq-agent/token: the file was deleted and the daemon restarted, which is exactly how access is revoked. Pair again with the link it prints now." }, DlItem { term: "A paired agent is refused after its host was rebuilt", detail: "The daemon made itself a new certificate — its ~/.wisq-agent folder was deleted, or it now runs as another user — and the phone still pins the old one. A certificate that does not match is refused, never trusted, which is the point. Pair again with the new link." }, DlItem { term: "A VM is running but never gets a port", detail: "virsh domdisplay shows what the daemon sees. Three answers give no reachable port: a VM with no display at all, a SPICE display in TLS only, and a display on a unix socket. A display that listens only on the host itself does publish a port, but the phone will not reach it." }, DlItem { term: "The phone does not see the host", detail: "Same network? The host's firewall has to let through 7442 for the agent and the console's own ports, 5900 and up." }, DlItem { term: "Connecting to a powered-off VM ends in « Délai d'attente dépassé »", detail: "The VM did not report running with a console port within 90 seconds. One without a reachable console never will — see the entry two above; one that stopped on its way up is reported as such instead." }, DlItem { term: "The agent says a domain is unknown", detail: "The daemon asks libvirt through virsh, so it sees exactly what `virsh list --all` sees — and as the user the daemon runs as. A VM defined for root is invisible to a daemon running as you. For an ordinary user virsh speaks qemu:///session; LIBVIRT_DEFAULT_URI=qemu:///system in the daemon's environment points it at the system's VMs." }, DlItem { term: "The pairing link does nothing", detail: "The link only opens wisq if the app is installed. On a fresh phone, install first, then scan." }, DlItem { term: "The local kernel boots and then stops printing", detail: "That is usually the login prompt, which ends without a newline. Type into it — the console is two-way. On the PC machine, look at the line under the console as well: if the count still moves, the machine is working." }, DlItem { term: "A PC kernel panics with « VFS: Unable to mount root fs »", detail: "It started without its initramfs, and a distribution kernel keeps its disk drivers there. Import the initramfs next to it, named to match, or as the only one in the library." }, DlItem { term: "wisq says the local disk was never touched", detail: "The kernel has no block driver for it, and wisq cannot add one to a kernel you brought. The disk is fine; the kernel cannot see it." }, DlItem { term: "The memory slider stops lower than expected", detail: "It only offers what fits now: what iOS lets the app allocate, less what the app keeps for itself, and never more than the architecture allows. Close what runs beside it and come back." }]),
    ],
};

pub static DOCS_FR: Doc = Doc {
    title: "Guide",
    lede: "Comment fonctionnent les deux moitiés, et ce que chacune demande : une VM sur votre matériel, ou Linux sur le téléphone lui-même.",
    blocks: &[
        Block::P("wisq fait deux choses distinctes, et savoir laquelle vous voulez décide de tout le reste. Atteindre une machine virtuelle qui tourne sur un Mac, un PC ou un NAS donne un bureau complet à la vitesse de cette machine. Démarrer Linux sur le téléphone lui-même donne un shell sans le moindre réseau. Ni l'un ni l'autre n'exige de jailbreak."),
        Block::Note { tone: Tone::Info, text: "L'application n'existe qu'en français pour l'instant : ses boutons et ses menus sont cités ici tels qu'elle les affiche — « Nouvelle machine », « Importer depuis un agent ». Tout part du menu + au-dessus de la liste des machines." },
        Block::H2("Distant : une VM sur votre matériel"),
        Block::P("wisq parle trois protocoles de console. RFB 3.8 — VNC — atteint tout ce qui expose une console VNC : QEMU, libvirt, VirtualBox, Proxmox, un Raspberry Pi sous x11vnc, un Mac qui partage son écran. SPICE atteint ce que les hôtes libvirt publient plutôt d'habitude, et transporte davantage : le presse-papiers, des fichiers envoyés dans l'invité, ses propres codecs d'image, et le son dans les deux sens — sur le fil, pour l'instant, comme l'explique la section SPICE plus bas. RDP atteint les invités Windows, avec une réserve à lire avant de s'y fier : wisq parle la sécurité historique de RDP et rien d'autre pour l'instant, laquelle n'authentifie pas le serveur — le certificat est signé par une clé que Microsoft a publiée en 1998. Un hôte qui exige NLA ou TLS est refusé par son nom plutôt que contourné, et le presse-papiers comme le son voyagent sur des canaux virtuels que wisq n'ouvre pas."),
        Block::Code { code: "qemu-system-x86_64 -m 2048 -vnc :1 -hda disk.qcow2\n\n# ou exposer un affichage qui existe déjà\nx11vnc -display :0 -rfbport 5901", caption: Some("Deux façons d'obtenir une console à laquelle se connecter") },
        Block::H3("Ajouter une machine à la main"),
        Block::Ol(&["Ouvrez le menu +, choisissez « Nouvelle machine » et donnez-lui un nom que vous reconnaîtrez.", "Saisissez l'adresse — un hôte, ou hôte:port. Un affichage VNC :1 signifie le port 5901 : le port vaut 5900 plus le numéro d'affichage. libvirt distribue les ports SPICE de la même façon, à partir de 5900, et le port propre à RDP est le 3389. Sans port, wisq essaie celui qu'emploie d'habitude le protocole.", "Choisissez le protocole. RDP ajoute un champ utilisateur ; VNC et SPICE ne demandent jamais qu'un mot de passe.", "Saisissez le mot de passe si le serveur en demande un ; il est rangé dans le trousseau de l'iPhone, jamais dans la liste des machines ni dans une sauvegarde iCloud.", "Enregistrez, puis touchez la machine pour vous connecter."]),
        Block::P("L'authentification VNC historique, c'est du DES sur un défi — faible par construction — et elle ne lit jamais que les 8 premiers caractères d'un mot de passe : un mot de passe plus long n'est pas plus solide, il est coupé. C'est aussi la seule authentification RFB que wisq parle en dehors de l'absence d'authentification : un serveur qui ne propose rien d'autre, VeNCrypt seul par exemple, est refusé avec « aucune méthode d'authentification commune ». Sous « Chiffrement », TLS enveloppe toute la connexion dès son premier octet, pour un serveur qui écoute derrière TLS ; « TLS épinglé par empreinte » n'accepte que le certificat dont vous saisissez l'empreinte SHA-256 — openssl x509 -fingerprint -sha256 l'affiche — et, sans empreinte, c'est du TLS ordinaire validé par le système, ce que l'éditeur dit sous le sélecteur."),
        Block::P("On peut chercher dans la liste par nom, par hôte ou par étiquette. Faire glisser une ligne vers la gauche propose « Modifier » et « Supprimer », et « Éteindre » sur une machine liée à un agent."),
        Block::Note { tone: Tone::Warn, text: "L'agent parle TLS par défaut : un certificat auto-signé dont l'empreinte voyage dans le lien d'appairage, épinglé par l'application, donc aucune autorité de certification dans le tableau. Ne le lancez avec --no-tls que derrière un tunnel qui chiffre déjà. La console, elle, est une autre affaire : le VNC nu et le SPICE nu ne sont pas chiffrés par construction — réseau de confiance, ou tunnel que vous exploitez déjà, WireGuard ou Tailscale." },
        Block::H3("Quel protocole pour quel hôte"),
        Block::Table { columns: &["Hôte", "Console", "Ce qu'il faut savoir"], rows: &[&["QEMU seul", "VNC avec -vnc :N, sur 5900 plus N ; SPICE sur le port que vous lui donnez", "L'agent n'a pas encore de backend pour QEMU sans libvirt : démarrez la VM vous-même, et saisissez le port SPICE — celui que wisq devine est 5900."], &["libvirt — virsh, virt-manager", "SPICE ou VNC, selon ce que déclare le domaine ; ports automatiques à partir de 5900", "Ce que l'agent pilote, via virsh ; sa commande bureau construit un bureau SPICE à partir d'une image d'installation."], &["Proxmox", "SPICE, par le fichier .vv que remet sa console", "wisq lit ces fichiers, mais son lecteur est testé sur des fichiers calqués sur ceux de Proxmox, pas contre un hôte Proxmox. L'agent n'a pas encore de backend Proxmox ; il est sur la feuille de route."], &["Windows", "RDP, sur le port 3389", "Les Windows modernes exigent NLA par défaut, que wisq ne parle pas encore : un tel hôte est refusé par son nom, si bien qu'une machine Windows laissée dans ses réglages d'origine est hors d'atteinte pour l'instant."], &["Un bureau Linux", "VNC par x11vnc, ou RDP par xrdp", "x11vnc partage un affichage qui existe déjà. xrdp est le serveur contre lequel le RDP de wisq a été écrit et mesuré."]] },
        Block::H3("Ouvrir un fichier .vv ou .rdp"),
        Block::P("Quand un hyperviseur ou une passerelle vous remet un fichier de connexion, rien n'est à ressaisir. Faites venir le fichier sur le téléphone — AirDrop, Mail, Fichiers — puis choisissez « Ouvrir un fichier .vv ou .rdp » dans le menu +. Le sélecteur accepte n'importe quel fichier, exprès, parce que ces fichiers arrivent sous le nom que leur a donné l'expéditeur : ce que wisq en fait se décide en le lisant. Une section [virt-viewer] fait un .vv, des lignes clé:type:valeur font un .rdp, et un .rdp enregistré par Windows en UTF-16 est lu comme tel. Un hôte qui n'est pas une adresse valable est refusé sur-le-champ, pas au moment de se connecter. Sinon la machine s'ouvre dans l'éditeur au lieu d'être enregistrée d'office, nommée d'après son hôte et étiquetée « importé », pour que vous voyiez ce qui arrive avant que cela n'entre dans votre liste."),
        Block::Ul(&["D'un .vv : l'hôte, le port — le port TLS quand le fichier en propose un, et la machine est alors marquée TLS —, le protocole, SPICE sauf si le fichier en nomme un autre, et le mot de passe, qui va au trousseau. C'est souvent un ticket à usage unique, valable pour une seule connexion.", "Pas d'un .vv : le sujet de certificat qu'un fichier TLS peut nommer. La machine n'a nulle part où le garder, donc l'import annonce du TLS validé par le système plutôt qu'un épinglage qu'il ne pourrait pas tenir.", "D'un .rdp : l'adresse, IPv6 entre crochets comprise, le port — 3389 quand le fichier n'en nomme aucun — et le nom d'utilisateur. Le mot de passe enregistré n'est jamais lu : il est chiffré pour l'ordinateur qui a écrit le fichier.", "Pas d'un .rdp : la taille d'écran. Elle décrit le moniteur de qui a enregistré le fichier, et sur un téléphone, c'est la taille de la vue qui compte."]),
        Block::H2("En session"),
        Block::P("Un doigt pilote toujours le pointeur. En mode trackpad — le défaut — il déplace le curseur par rapport à là où il était, comme le trackpad d'un portable, et une tape clique là où se trouve le curseur ; en mode tactile direct, le curseur va sous le doigt. Le trackpad est le défaut parce que viser un petit bouton du bout du doigt ne marche pas, et que le curseur dessiné rend ce que le doigt cache."),
        Block::Table { columns: &["Geste", "Par défaut", "Réglable"], rows: &[&["Un doigt qui glisse", "déplace le pointeur", "non"], &["Tape", "clic gauche", "non"], &["Tape à deux doigts", "clic droit", "oui"], &["Appui long", "clic droit", "oui, « Glisser » compris, qui tient le bouton enfoncé"], &["Deux doigts qui glissent", "molette", "oui"], &["Trois doigts qui glissent", "déplace la vue", "oui"], &["Balayage à trois doigts", "vers le haut affiche le clavier, vers le bas le masque", "activé ou non"], &["Pincement", "zoom", "non"], &["Double tape", "affiche ou masque la barre du haut", "non"]] },
        Block::P("Les choix sont les mêmes pour chaque geste — rien, un clic gauche, droit ou milieu, « Glisser », « Déplacer l'écran », la molette, le clavier — et ils se règlent par machine, dans son éditeur sous « Gestes », parce que la bonne réponse dépend de savoir si le bureau distant tient sur l'écran du téléphone : déplacer une vue qui n'a nulle part où aller est un geste gaspillé. Le même éditeur règle la vitesse du pointeur, le défilement naturel, le retour haptique et l'inertie : activée, elle laisse le pointeur et la molette continuer un instant sur leur lancée quand le doigt se lève."),
        Block::P("Deux détails sont là pour l'invité. Un clic ou une frappe synthétisés envoient l'appui et le relâchement à 50 ms d'intervalle, parce qu'un invité qui échantillonne ses entrées sur une horloge ne voit rien de deux fronts arrivés ensemble. Et les entrées atteignent l'invité dans l'ordre où elles ont eu lieu : un clic qui doublerait le déplacement qui l'a placé tomberait au mauvais endroit. Quand le serveur cède l'image de son curseur — l'encodage curseur de VNC, le canal curseur de SPICE —, le téléphone la dessine à son point chaud, dans une couche à part, si bien qu'elle suit le doigt sans redessiner le bureau ; en mode trackpad, un anneau en tient lieu jusqu'à ce qu'elle arrive."),
        Block::H3("Les claviers"),
        Block::P("Un clavier matériel fonctionne dès que la session est ouverte : une vue invisible écoute pendant toute la session, et les touches qu'il rapporte sont traduites en ce que veut le protocole — des keysyms X11 pour VNC, des scancodes pour SPICE et RDP. « ⌘ vers la touche Super » décide où va Commande : vers la touche Super de l'invité ou, désactivé, vers Contrôle, ce que veulent les habitudes de macOS dans un terminal. Le clavier à l'écran va et vient avec le bouton clavier de la barre du haut, ou par un balayage à trois doigts. Le bouton ⌘ à côté ouvre une rangée des touches qui manquent à un clavier de téléphone : esc, tab, ctrl, alt, ⇧ et ⌘, les flèches, début, fin, page précédente et suivante, suppr, et « Fn » pour F1 à F12. Ses modificateurs sont collants — touchez ctrl, puis une lettre, et la paire part ensemble."),
        Block::H3("La barre du haut"),
        Block::Ul(&["Le bouton de fermeture met fin à la session.", "Le bouton presse-papiers envoie le texte du presse-papiers du téléphone à l'invité. L'autre sens n'a pas besoin de bouton : un texte copié dans l'invité arrive tout seul dans le presse-papiers du téléphone. VNC et SPICE le transportent ; RDP pas encore.", "Le bouton de partage, en session SPICE seulement, sert à envoyer un fichier dans l'invité — la section SPICE plus bas dit pourquoi il n'en atteint pas encore.", "Les boutons ⌘ et clavier, décrits plus haut.", "Une double tape sur le bureau masque la barre, et une autre la fait revenir."]),
        Block::H3("Les réglages d'affichage"),
        Block::Dl(&[DlItem { term: "« Échelle »", detail: "« Ajusté » fait tenir tout le bureau à l'écran, avec des bandes ; « 1:1 » montre un pixel distant par pixel et vous vous déplacez dedans ; « Rempli » l'étire pour remplir, sans respecter ses proportions." }, DlItem { term: "« Suivre la résolution de l'appareil »", detail: "Demande au serveur de retailler son bureau à la vue du téléphone. Un serveur VNC qui sait se retailler le fait. RDP fixe sa taille à l'ouverture de la session, et wisq ne sait pas encore la renégocier ; SPICE se retaille par l'agent de l'invité, que wisq ne pilote pas encore." }, DlItem { term: "« Mode bas débit »", detail: "VNC seulement. Place en tête les encodages qui compressent le plus et demande au serveur plus de compression que son défaut. Il ne réduit pas la profondeur de couleur." }, DlItem { term: "« JPEG (avec pertes) »", detail: "VNC seulement, par Tight : autorise le serveur à envoyer du JPEG, à une qualité de 0 à 9. Désactivé, la session reste sans perte — aucune qualité n'est annoncée, donc un serveur conforme n'envoie jamais de JPEG. Sur un lien cellulaire, la perte est en général le bon compromis." }, DlItem { term: "« Garder l'écran allumé »", detail: "Empêche le téléphone de se verrouiller tant que la session est ouverte. Activé par défaut." }]),
        Block::H3("Quand le réseau tombe"),
        Block::P("Un téléphone change de réseau sans arrêt, et chaque bascule tue la socket. wisq garde la session et reconstruit la connexion en dessous : jusqu'à 5 tentatives, en attendant 1 seconde avant la première et le double à chaque fois. Pendant ce temps l'écran cède la place à « Reconnexion (tentative n)… » : chaque tentative repart de zéro, parce qu'un dictionnaire de compression hérité de la connexion morte décoderait n'importe quoi, et ce que vous tapez entre-temps est jeté plutôt que mis en file. Quand wisq abandonne, il affiche la raison avec « Réessayer » et « Fermer ». Une connexion restée debout 10 secondes regagne tout son crédit ; une connexion qui monte et retombe aussitôt, non, si bien qu'un hôte qui accepte puis lâche ne peut pas faire réessayer le téléphone indéfiniment."),
        Block::P("Il ne réessaie jamais un refus. Un mauvais mot de passe, une négociation ratée, un certificat qui ne correspond pas : ceux-là terminent la session avec leur raison, parce que marteler un serveur avec un mauvais mot de passe peut verrouiller le compte, et qu'un désaccord de protocole ne se réglera pas tout seul. Une limite connue : une reconnexion recompose le port sur lequel la session a commencé. Si libvirt a donné un autre port à la VM entre-temps, parce qu'elle a été redémarrée depuis l'hôte, fermez la session et reconnectez-vous depuis la liste, qui redemande à l'agent."),
        Block::H2("SPICE : ce qui voyage à côté de l'écran"),
        Block::P("SPICE ouvre une connexion par canal — affichage, entrées, curseur, le son de l'invité, le micro du téléphone — et tout sauf l'affichage est en meilleur effort : un serveur qui n'offre pas de canal curseur donne quand même un écran utilisable. Le canal principal porte aussi l'agent invité, et c'est par lui que passent le presse-papiers et les transferts de fichiers. Cela a une conséquence dans l'invité : spice-vdagent doit y tourner, et le domaine doit porter le canal com.redhat.spice.0 par lequel il parle — celui que la commande bureau de l'agent ajoute d'elle-même. Sans eux, l'écran et les entrées marchent toujours, le presse-papiers reste simplement muet, et un transfert de fichier dit « aucun agent ne tourne dans l'invité pour recevoir le fichier »."),
        Block::P("Copiez quelque chose dans l'invité et cela arrive dans le presse-papiers du téléphone ; le bouton presse-papiers envoie le texte du téléphone dans l'autre sens. L'envoi de fichiers est écrit jusqu'au protocole : un fichier coule vers l'agent de l'invité par tranches, sans jamais être tenu entier en mémoire, si bien que sa taille est l'affaire de l'invité plutôt que du téléphone, et quand l'invité refuse, le message dit pourquoi — transferts désactivés, place insuffisante, chiffres à l'appui. L'écran de session ne l'atteint pas encore. Le bouton de partage cherche une session SPICE là où l'application tient l'enveloppe de reconnexion qui l'entoure, donc il répond aujourd'hui « cette session n'a pas d'agent SPICE pour recevoir un fichier » quoi que fasse l'invité — un défaut connu, pas un agent absent. Le presse-papiers est testé contre le protocole et n'a pas encore été vu fonctionner contre un invité démarré avec son agent en marche, et le parcours Ubuntu du dépôt le dit."),
        Block::P("Le son est l'exception honnête. Le canal de lecture — le son de l'invité — et le canal d'enregistrement — le micro du téléphone, vers l'invité — sont tous deux parlés et testés, en PCM brut seulement : Opus et CELT sont nommés plutôt que décodés, parce que des octets compressés joués comme des échantillons font du bruit à plein volume. Ce qui n'est pas encore écrit, c'est la partie qui demande un haut-parleur et un micro. Rien sur le téléphone ne joue aujourd'hui le son de l'invité ni ne capte le vôtre : une session SPICE est muette, et ce n'est pas un réglage. Les flux vidéo suivent la même règle du nom : le MJPEG est décodé là où la plateforme a un décodeur JPEG, et les autres codecs qu'un serveur peut choisir vous sont nommés plutôt que montrés comme un rectangle figé."),
        Block::H2("L'agent : allumer une VM avant de s'y connecter"),
        Block::P("Sans agent, wisq fonctionne — il faut simplement que la VM soit déjà démarrée. L'agent est ce qui transforme « un client VNC de plus » en « mes machines, depuis mon téléphone » : toucher une VM éteinte la démarre, attend sa console et s'y connecte sur le port qu'elle a obtenu."),
        Block::P("Le démon n'a pas de mode service à lui, et un argument qu'il ne connaît pas l'arrête sur « argument inconnu ». Ce qui le garde en vie d'un redémarrage à l'autre, c'est ce qui le lance — un agent launchd sur macOS, une unité systemd utilisateur sur Linux — et le jeton comme les liens d'appairage se lisent alors dans le journal de ce service — ~/Library/Logs/wisq-agent.log sur un Mac, journalctl --user -u wisq-agent sur Linux. Avec --demo, il sert deux VM factices aux transitions d'état réelles, sans console derrière : de quoi vérifier le côté téléphone avant de le pointer vers un hyperviseur."),
        Block::P("Au premier lancement, le démon imprime un lien d'appairage par adresse joignable, et un QR code si qrencode est installé. Ouvrez-en un sur l'iPhone — scanné ou collé — et wisq arrive sur l'écran d'import, adresse et jeton déjà remplis."),
        Block::Code { code: "wisq-agent en écoute sur le port 7442 (virsh)\njeton : k3f9x2m8q1w7e4r6t5y0u8i2o4p6a1s3\nappairage :\n  wisq://agent?host=nas&port=7442&token=…&name=nas", caption: Some("Ce que le démon imprime") },
        Block::P("Le jeton est généré une fois et conservé dans ~/.wisq-agent/token, lisible par son seul propriétaire. Révoquer un accès, c'est supprimer ce fichier et relancer le démon — le supprimer sous un démon qui tourne ne change rien, puisque le jeton est lu une fois au démarrage —, et chaque téléphone appairé avec l'ancien jeton doit alors s'appairer de nouveau."),
        Block::H3("Appairage, découverte et certificat"),
        Block::P("Le démon imprime un lien par adresse — son nom d'hôte d'abord, puis chaque adresse IPv4 qu'il trouve — et le QR code porte le premier. Si celui-là ne répond pas depuis le téléphone, collez-en un autre. Outre le jeton, chaque lien porte l'empreinte SHA-256 du certificat auto-signé du démon : c'est elle qui fait parler HTTPS au téléphone et accepter exactement ce certificat, sans autorité et sans vérification de nom. Le certificat ne tourne jamais tout seul, donc les liens déjà imprimés continuent de marcher ; supprimer tls-certificate.der et tls-key.der de ~/.wisq-agent est la rotation, et elle invalide à dessein tous les anciens liens."),
        Block::P("L'écran d'import liste aussi les agents qu'il entend sur le réseau local — le démon s'annonce en Bonjour sous son nom d'hôte quand avahi-publish-service ou dns-sd est présent — et une tape remplit l'adresse. Une adresse trouvée ainsi, ou saisie à la main, n'a pas d'empreinte à épingler, donc le téléphone lui parle en HTTP clair : juste pour un démon lancé avec --no-tls, et un démon dans son mode par défaut répond « cet agent parle TLS ». Pour celui-là, le lien d'appairage est la porte d'entrée."),
        Block::H3("Les options du démon"),
        Block::Dl(&[DlItem { term: "--port N", detail: "Le port d'écoute ; 7442 par défaut." }, DlItem { term: "--token SECRET", detail: "Un jeton de votre choix. Sans lui, le démon prend celui de ~/.wisq-agent/token, tiré de la source d'aléa du système au premier lancement." }, DlItem { term: "--no-tls", detail: "HTTP en clair, pour un tunnel qui chiffre déjà. Le jeton reste obligatoire, et les liens d'appairage ne portent alors pas d'empreinte." }, DlItem { term: "--demo", detail: "Deux VM factices au lieu de libvirt. Un démarrage passe par l'état starting, que l'application affiche « Démarrage… » ; un arrêt poli prend un moment, un arrêt forcé est immédiat." }, DlItem { term: "--virsh CHEMIN", detail: "Le virsh à piloter ; /usr/bin/virsh par défaut." }, DlItem { term: "--demo-delay MS", detail: "La durée d'un démarrage de démonstration. Elle existe pour que les tests qui lancent le vrai démon contre le client de l'application traversent vite le passage de starting à running." }]),
        Block::H3("Démarrer et éteindre depuis le téléphone"),
        Block::P("Une machine importée depuis un agent lui est liée ; une machine ajoutée à la main peut l'être dans son éditeur, sous « Démarrer via un agent », avec l'identifiant de la VM et le jeton. La connexion passe alors d'abord par l'agent. Si la VM est éteinte, l'agent la démarre — sauf si « Démarrer la VM à la connexion » est désactivé, et wisq le dit alors à la place — et le téléphone demande l'état de la VM toutes les 2 secondes, pendant 90 au plus, jusqu'à ce qu'elle tourne et annonce un port de console. Les deux moitiés comptent : libvirt dit running dès que le domaine existe, et ouvre le port de console à ce moment-là, alors que l'invité derrière peut mettre des dizaines de secondes à avoir quoi que ce soit à montrer. La console est ensuite jointe sur l'hôte de l'agent, au port et dans le protocole que l'agent vient de donner — c'est pourquoi un port qui bouge d'un démarrage à l'autre n'a pas d'importance sur ce chemin."),
        Block::P("Pour éteindre une VM, faites glisser sa ligne vers la gauche, choisissez « Éteindre », puis « Demander l'arrêt ». C'est le bouton ACPI : l'invité reçoit la demande, et peut mettre une minute à obéir — ou ne jamais le faire, s'il n'a pas de gestionnaire ACPI, puisque rien dans le protocole ne peut l'y forcer. wisq guette pendant 90 secondes au plus ; au-delà, il dit « L'invité n'a pas répondu » et propose « Couper l'alimentation », le cordon, qui arrête la VM aussitôt et perd ce qui n'était pas enregistré."),
        Block::H3("Un bureau à partir d'une image d'installation"),
        Block::P("wisq-agent bureau construit la machine à laquelle se connecter. Écrire un domaine libvirt à la main demande de connaître le modèle de carte graphique qui va avec le compositeur du bureau, l'ordre d'amorçage, le canal de l'agent invité et le mot de passe SPICE — quatre occasions de se tromper, dont trois finissent en écran noir sans message. Donnez plutôt une image d'installation à la commande : elle crée un disque qcow2, écrit le domaine, le définit et le démarre, puis affiche ce qu'il faut taper dans wisq. Dedans : l'image amorcée avant le disque et montée en lecture seule, une tablette USB — SPICE envoie des coordonnées absolues, ce qu'un doigt produit, et une souris relative dérive jusqu'à devenir impossible à poser —, la carte son ich9, le canal de l'agent invité, et un mot de passe SPICE tiré de /dev/urandom."),
        Block::Code { code: "wisq-agent bureau --image ~/debian.iso\n\n…\nLa machine « debian » tourne.\n\nDans wisq, ajoutez une machine :\n  hôte      nas.local\n  protocole SPICE\n  port      celui que l'agent annonce pour cette machine\n  mot de passe  …\n\nLe mot de passe n'est écrit nulle part ailleurs : notez-le maintenant.", caption: Some("D'une image à un bureau qui tourne, et ce que la commande imprime en dernier") },
        Block::Dl(&[DlItem { term: "--image CHEMIN", detail: "L'image d'installation, et la seule option obligatoire." }, DlItem { term: "--nom N", detail: "Le nom de la machine ; par défaut, celui du fichier sans son extension." }, DlItem { term: "--memoire Mio, --processeurs N", detail: "4096 Mio et 4 processeurs sauf indication contraire." }, DlItem { term: "--disque Gio", detail: "La taille du disque, 64 Gio par défaut, créé épars. Un disque du même nom qui existe déjà est réutilisé, jamais écrasé : redéfinir une machine ne doit pas effacer un système déjà installé dessus." }, DlItem { term: "--video virtio|qxl", detail: "virtio par défaut, le bon modèle pour un bureau Wayland — Hyprland, GNOME, KDE ; qxl pour un X11 léger. Se tromper ne casse rien : la machine démarre et l'écran reste noir." }, DlItem { term: "--ecoute ADRESSE", detail: "Là où le bureau écoute ; toutes les interfaces par défaut, pour que le téléphone l'atteigne. C'est le mot de passe engendré qui le garde, et il est imprimé une fois, nulle part ailleurs." }, DlItem { term: "--dossier DIR", detail: "Où vont le disque et le XML du domaine ; ~/wisq-disques par défaut. Le XML y reste pour être relu." }, DlItem { term: "--montrer", detail: "Écrit le domaine sur la sortie standard et ne crée rien, pour le relire ou l'adapter. Il n'a besoin d'aucun libvirt." }]),
        Block::P("L'accélérateur est lu dans virsh capabilities plutôt que deviné : KVM sous Linux, HVF sur un Mac, et sinon l'interprète de QEMU lui-même, ce que la commande dit alors tout haut, parce qu'un bureau interprété tourne, lentement. Pour atteindre le résultat, importez-le depuis l'agent, qui connaît son port, et ajoutez le mot de passe imprimé dans l'éditeur de la machine. La commande a été lancée pour de vrai contre libvirt et QEMU avec une image Alpine : le disque est créé, le domaine défini et démarré, et le client SPICE de wisq s'y connecte avec le mot de passe engendré et reçoit les pixels du bureau, tandis qu'un mauvais mot de passe est refusé. L'installation complète d'un invité depuis son installateur n'a pas été vérifiée."),
        Block::H2("Local : Linux sur le téléphone lui-même"),
        Block::P("Le côté local, ce sont deux ordinateurs interprétés, et wisq choisit entre eux en lisant le fichier que vous apportez. Le RISC-V est un hart rv32ima, 64 Mo de RAM par défaut et jusqu'à 2 Go si vous le demandez, un UART 8250, un minuteur CLINT ; il amène un vrai noyau Linux jusqu'à l'invite de connexion en une fraction de seconde. L'autre est un PC x86-64, décrit plus bas. Tous deux tournent sans réseau et sans hôte."),
        Block::Ol(&["Procurez-vous un noyau. Pour la machine RISC-V, une image rv32ima nommu — le projet mini-rv32ima en propose des prêtes à l'emploi. Pour le PC, un bzImage et son initramfs.", "Placez les fichiers où l'app Fichiers peut les lire — iCloud Drive, ou Sur mon iPhone.", "Dans wisq, choisissez « Linux local (sur ce téléphone) » dans le menu + et importez-les, un à la fois.", "Facultatif : importez aussi une image de système de fichiers ou d'installation, de n'importe quelle taille, et choisissez-la sous le noyau comme son disque. L'invité la voit sur /dev/vda.", "Touchez le noyau. La console apparaît au fil de ce que le noyau écrit sur son port série ; tapez dans le champ en dessous et appuyez sur « Entrée », ou envoyez ^C."]),
        Block::P("Sur la machine RISC-V, l'horloge virtuelle avance avec les instructions exécutées et non avec le temps réel : la même image démarre donc de la même façon sur chaque appareil — ce qui est aussi ce qui rend ce démarrage testable en intégration continue."),
        Block::H3("Quelle machine pour quel fichier"),
        Block::P("wisq lit les 40 premiers Kio d'un fichier — de quoi atteindre le descripteur de volume d'une image d'installation, jamais l'image entière — et décide d'après eux. Il connaît les emballages sous lesquels un noyau est vraiment livré : ELF, bzImage, l'Image d'ARM64 et celle de RISC-V, le zImage d'ARM, et l'uImage d'U-Boot, qui nomme sa propre architecture. Il reconnaît toutes les architectures pour lesquelles Linux a un répertoire sous arch/, plus quelques-unes qu'il a portées assez longtemps pour que des images traînent encore — x86, ARM, RISC-V, MIPS, PowerPC, IBM Z, SPARC, LoongArch et les autres — et il en exécute deux : RISC-V 32 bits et x86-64. Un noyau pour une autre est refusé en nommant son architecture, ce qui dit quoi chercher à la place ; un noyau x86 32 bits ou RISC-V 64 bits est refusé aussi, faute de cœur. Un fichier que rien ne reconnaît n'est pas refusé : il est essayé sur la machine RISC-V, parce qu'une image brute sans en-tête peut quand même être un noyau."),
        Block::Table { columns: &["Ce que vous apportez", "Ce que wisq en fait", "Qui décide"], rows: &[&["Un noyau", "il le démarre, sur le cœur que ses octets demandent", "les octets"], &["Un initramfs", "il le donne au noyau du PC, qui le déballe ; la machine RISC-V en refuse un, nommément", "son nom, puis vous"], &["Une image de disque", "il la branche sur /dev/vda", "vous, dans le menu « Disque » du noyau"], &["Une image d'installation", "il en sort le noyau et l'initramfs, et branche l'image comme disque", "la recette d'amorçage qu'elle contient"]] },
        Block::P("Un initramfs va au noyau dont le nom lui répond — vmlinuz-lts et initramfs-lts, dans la façon de nommer d'Alpine — ou, à défaut, au seul de la bibliothèque. Les octets ne peuvent pas trancher : un noyau compressé et un initramfs compressé sont l'un et l'autre un flux gzip, donc c'est le nom qui décide, puis vous."),
        Block::H3("La machine x86-64"),
        Block::P("La machine PC interprète le x86-64 et démarre un noyau Alpine d'origine avec son initramfs. Son port série passe la sonde du pilote du noyau lui-même, si bien que l'espace utilisateur a une vraie console ; autour, un minuteur et un contrôleur d'interruptions, un bus PCI, et un disque virtio que le noyau trouve par MMIO ou par PCI. Mesuré sur les mêmes images que QEMU, l'init d'Alpine finit sur « Mounting boot media: failed. » et ouvre le shell de secours de l'initramfs — exactement là où QEMU finit — et vous pouvez taper dedans. Prévoyez d'attendre : là où le noyau RISC-V atteint son invite en quelques dizaines de millions d'instructions, il en faut quelque 4 milliards. Une ligne sous la console les compte, donne la vitesse, et dit « figée » avec l'adresse quand rien n'a bougé depuis un moment, parce qu'un noyau qui imprime quelques lignes puis se tait ressemble trait pour trait à un noyau mort."),
        Block::P("Un noyau de PC reçoit ce que dit son curseur de mémoire, mais jamais moins de 128 Mo : en dessous, son noyau n'a pas la place de se décompresser, et avec le curseur laissé à son défaut c'est ce plancher qu'il reçoit. La machine sait donner un écran au noyau, et un vrai noyau Alpine le trouve et le mappe en test, mais l'application n'en branche encore aucun : le PC est une console, comme l'autre machine. Aucune des deux n'a de périphérique réseau."),
        Block::H3("Les images d'installation"),
        Block::P("Une image d'installation n'est plus refusée dans la construction qui porte le cœur Rust, celle que l'application embarque. wisq lit la recette d'amorçage qu'elle contient — syslinux, grub ou systemd-boot —, en sort le noyau et l'initramfs dans son propre stockage, et les démarre avec la ligne de commande que donne la recette : lue, jamais inventée, parce qu'un noyau démarré sans la sienne ne trouve pas sa racine, et que la panne tombe loin de sa cause. Seul quiet est retiré, et la console série de wisq est ajoutée en dernier, puisque c'est la seule sortie qui existe. L'image elle-même reste où elle est et devient le disque, lue secteur par secteur, parce que la racine que nomme cette ligne de commande vit là. Une recette qui promet un initramfs que l'image ne contient pas est un refus plutôt qu'un démarrage qui meurt trois cents lignes plus loin. Sur une image live, dont la racine est en lecture seule, tout ce que vous faites vit en RAM, et c'est l'instantané décrit plus bas qui le garde. Supprimer l'image supprime ce qui en a été déballé. Jusqu'où une distribution donnée va ensuite sur l'interprète, c'est à la console de le dire ; ce guide ne le promet pas."),
        Block::H3("La mémoire"),
        Block::P("Chaque noyau de la liste a son propre curseur de mémoire, retenu sous le nom du fichier. Il propose des puissances de deux à partir de 16 Mo, mais seulement aussi loin que le téléphone le permet à cet instant : le plus petit de ce qu'iOS dit que l'application peut encore allouer, moins 256 Mo que l'application garde pour elle ; de la mémoire du téléphone, moins 2 Go ; et de ce que permet l'architecture — 2 Go pour la machine RISC-V, le dernier octet qu'un processeur rv32 peut adresser, et 16 Go pour le PC. Le plafond est relu au démarrage, et une machine qui ne tient plus est refusée avec une explication plutôt que démarrée puis tuée par iOS en chemin. Changer ce réglage repart du noyau : un instantané pris à une autre taille ne peut pas être repris."),
        Block::H3("Suspension et reprise"),
        Block::P("Quitter la console n'arrête pas la machine : cela la suspend. Quittez l'écran, ou laissez iOS reprendre l'application, et wisq écrit la machine entière dans un instantané — processeur, RAM, entrées en attente, sortie pas encore affichée, écritures du disque vidées — et la visite suivante la reprend là où elle était, console comprise. Une machine RISC-V arrivée à son invite de connexion pèse environ 17 Mio une fois sauvegardée, parce que l'instantané garde ce que l'invité a touché, pas ce qu'on lui a donné. « Arrêter » met fin à la machine et oublie son instantané ; « Oublier » jette l'instantané sans arrêter la machine qui tourne, pour un invité coincé qu'on veut retrouver propre. Les instantanés sont classés sous les octets du noyau, pas sous son nom, si bien qu'un autre noyau qui s'appelle lui aussi Image n'hérite jamais de la machine d'un autre ; changer la mémoire d'un noyau ou son disque oublie ses machines sauvegardées."),
        Block::H3("Le disque"),
        Block::P("wisq émule le périphérique, et ne peut pas ajouter un pilote bloc au noyau que vous apportez. Beaucoup de noyaux rv32 nommu n'en ont pas, et un noyau qui n'en a pas n'y touchera jamais — alors le périphérique compte ses requêtes, et wisq vous le dit à la fin de la session plutôt que de vous laisser devant un disque muet pour une raison invisible. L'image est lue sur place, quelle que soit sa taille — il n'y a plus de plafond. Ce que l'invité écrit va dans une couche à côté — les secteurs touchés rangés les uns derrière les autres, 512 octets chacun, et une carte qui les nomme —, posée au fil des écritures, donc elle survit aux suspensions et aux redémarrages ; le fichier importé ne change jamais."),
        Block::P("Le menu + porte une entrée de plus, « Le bureau est-il possible ? ». Elle passe quelques secondes à mesurer si WebKit compile le WebAssembly sur ce téléphone-là — la seule inconnue dont dépend le travail sur un bureau local, puisqu'iOS n'autorise aucun JIT et que le WebAssembly compilé par WebKit est la seule porte qu'il laisse ouverte. Elle ne fait rien d'autre."),
        Block::H2("Quand quelque chose ne marche pas"),
        Block::Dl(&[DlItem { term: "L'écran reste noir après connexion", detail: "Le serveur a accepté la connexion mais n'envoie pas de mise à jour. Vérifiez que le serveur VNC est attaché à un affichage qui existe — un QEMU sans -vga se connecte et ne montre rien." }, DlItem { term: "Les couleurs sont fausses", detail: "Signalez-le. wisq négocie un format de pixels pour le rendu au lieu d'accepter celui du serveur : un décalage est un défaut de notre côté, pas un réglage du vôtre." }, DlItem { term: "VNC : « aucune méthode d'authentification commune »", detail: "Le serveur ne propose aucune authentification RFB que wisq parle ; seules l'absence d'authentification et le mot de passe VNC historique le sont. Un serveur réglé sur VeNCrypt seul, par exemple, doit proposer aussi le mot de passe VNC." }, DlItem { term: "« Cette machine demande un mot de passe »", detail: "Le serveur veut le mot de passe VNC et la machine n'en a aucun d'enregistré. Ajoutez-le dans l'éditeur ; il va au trousseau." }, DlItem { term: "RDP : « ce serveur exige l'authentification réseau (NLA) »", detail: "Les Windows modernes demandent NLA par défaut, et wisq ne le parle pas encore : il refuse en le nommant plutôt que d'échouer au milieu de la poignée de main, et rien sur le téléphone n'y change quoi que ce soit. Il en va de même de « ce serveur exige TLS » : wisq ne sait pas démarrer TLS dans une connexion déjà ouverte." }, DlItem { term: "Une session SPICE n'a pas de son", detail: "Normal, pour l'instant. Les canaux audio sont parlés et décodés, mais rien sur le téléphone ne les joue encore. Ce n'est pas un réglage." }, DlItem { term: "Le presse-papiers reste muet", detail: "spice-vdagent ne tourne pas dans l'invité, ou le domaine n'a pas de canal com.redhat.spice.0 par lequel il puisse parler. L'écran et les entrées n'ont besoin ni de l'un ni de l'autre. En RDP, le presse-papiers ne voyage pas du tout pour l'instant. Un envoi de fichier qui dit que la session n'a pas d'agent SPICE est le défaut connu décrit dans la section SPICE, quoi que fasse l'invité." }, DlItem { term: "La VM est revenue sur un autre port", detail: "libvirt attribue les ports de console à chaque démarrage, à partir de 5900, donc une VM redémarrée depuis l'hôte peut atterrir ailleurs. Une machine liée à l'agent demande le port à chaque connexion depuis la liste ; une session qui se reconnecte d'elle-même recompose l'ancien, donc fermez-la et reconnectez-vous. Une machine saisie à la main garde le port que vous lui avez donné : liez-la à l'agent, ou écrivez le port dans la définition du domaine." }, DlItem { term: "L'import depuis un agent répond « cet agent parle TLS »", detail: "L'adresse a été saisie, ou choisie parmi les agents trouvés sur le réseau, donc il n'y avait pas d'empreinte à épingler et le téléphone a parlé HTTP en clair. Ouvrez plutôt le lien d'appairage — ou lancez le démon avec --no-tls, derrière un tunnel." }, DlItem { term: "Un agent appairé répond « jeton manquant ou invalide »", detail: "Le jeton du lien n'est plus celui de ~/.wisq-agent/token : le fichier a été supprimé et le démon relancé, ce qui est précisément la façon de révoquer un accès. Appairez de nouveau avec le lien qu'il imprime maintenant." }, DlItem { term: "Un agent appairé est refusé après la reconstruction de son hôte", detail: "Le démon s'est fait un nouveau certificat — son dossier ~/.wisq-agent a été supprimé, ou il tourne maintenant sous un autre utilisateur — et le téléphone épingle toujours l'ancien. Un certificat qui ne correspond pas est refusé, jamais cru, et c'est tout l'intérêt. Appairez de nouveau avec le nouveau lien." }, DlItem { term: "Une VM tourne mais n'obtient jamais de port", detail: "virsh domdisplay montre ce que voit le démon. Trois réponses ne donnent aucun port joignable : une VM sans affichage du tout, un affichage SPICE en TLS seul, et un affichage sur socket unix. Un affichage qui n'écoute que sur l'hôte lui-même publie bien un port, mais le téléphone ne l'atteindra pas." }, DlItem { term: "Le téléphone ne voit pas l'hôte", detail: "Même réseau ? Le pare-feu de l'hôte doit laisser passer 7442 pour l'agent et les ports propres à la console, 5900 et suivants." }, DlItem { term: "Se connecter à une VM éteinte finit sur « Délai d'attente dépassé »", detail: "La VM n'a pas annoncé running avec un port de console dans les 90 secondes. Une VM sans console joignable ne le fera jamais — voir l'entrée deux crans plus haut ; une VM qui s'est arrêtée en démarrant est signalée comme telle à la place." }, DlItem { term: "L'agent dit qu'un domaine est introuvable", detail: "Le démon interroge libvirt via virsh : il voit exactement ce que voit `virsh list --all`, et sous l'utilisateur qui le fait tourner. Une VM définie pour root est invisible à un démon lancé sous votre compte. Pour un utilisateur ordinaire, virsh parle à qemu:///session ; LIBVIRT_DEFAULT_URI=qemu:///system dans l'environnement du démon le tourne vers les VM du système." }, DlItem { term: "Le lien d'appairage ne fait rien", detail: "Le lien n'ouvre wisq que si l'application est installée. Sur un téléphone neuf : installez d'abord, scannez ensuite." }, DlItem { term: "Le noyau local démarre puis cesse d'écrire", detail: "C'est généralement l'invite de connexion, qui se termine sans saut de ligne. Tapez dedans — la console fonctionne dans les deux sens. Sur la machine PC, regardez aussi la ligne sous la console : si le compte bouge encore, la machine travaille." }, DlItem { term: "Un noyau de PC panique sur « VFS: Unable to mount root fs »", detail: "Il a démarré sans son initramfs, et un noyau de distribution y range ses pilotes de disque. Importez l'initramfs à côté de lui, avec un nom qui lui réponde, ou comme le seul de la bibliothèque." }, DlItem { term: "wisq dit que le disque local n'a jamais été touché", detail: "Le noyau n'a pas de pilote bloc pour lui, et wisq ne peut pas en ajouter un au noyau que vous apportez. Le disque va bien ; c'est le noyau qui ne le voit pas." }, DlItem { term: "Le curseur de mémoire s'arrête plus bas que prévu", detail: "Il ne propose que ce qui tient maintenant : ce qu'iOS laisse allouer à l'application, moins ce que l'application garde pour elle, et jamais plus que ce que permet l'architecture. Fermez ce qui tourne à côté et revenez." }]),
    ],
};
